mapper.select:
SELECT DATE(commit_time) AS stat_date,
       COUNT(1) AS commit_count
FROM review_commit_fact
WHERE project_id = #{projectId}
  AND commit_time IS NOT NULL
  AND DATE(commit_time) >= #{beginDate}
  AND DATE(commit_time) <= #{endDate}
GROUP BY DATE(commit_time)
ORDER BY stat_date ASC

SELECT author_email, author_name, AS author_key, MAX(commit_time) AS commit_time FROM review_commit_fact
(
LOWER(TRIM(author_email)) = LOWER(TRIM(#{email}))
1 = 0
) OR ( author_name IS NOT NULL AND author_name != '' AND (
TRIM(author_name) = TRIM(#{userName})
1 = 0
OR TRIM(author_name) = TRIM(#{nickName})
) )
GROUP BY author_email, author_name, ORDER BY commit_time DESC LIMIT #{limit}

SELECT DATE(commit_time) AS stat_date, CASE WHEN author_email IS NOT NULL AND author_email != '' THEN LOWER(TRIM(author_email)) ELSE TRIM(author_name) END AS author_key, COUNT(1) AS commit_count FROM review_commit_fact WHERE commit_time IS NOT NULL AND DATE(commit_time) >= #{beginDate} AND DATE(commit_time) <= #{endDate}
AND ( CASE WHEN author_email IS NOT NULL AND author_email != '' THEN LOWER(TRIM(author_email)) ELSE TRIM(author_name) END ) IN
#{k}
AND project_id IN
#{pid}
GROUP BY DATE(commit_time), CASE WHEN author_email IS NOT NULL AND author_email != '' THEN LOWER(TRIM(author_email)) ELSE TRIM(author_name) END ORDER BY stat_date ASC
